{
  "name": "AI Video Wizard",
  "description": "Một ứng dụng wizard nhiều bước để tạo timeline chi tiết và prompt cho video AI với giao diện tối hiện đại.",
  "requestFramePermissions": []
}

export enum VisualStyle {
  RealPerson = 'Real Person',
  Animation3D = '3D Animation',
  Anime2D = '2D Anime',
  Cinematic = 'Cinematic',
  Cyberpunk = 'Cyberpunk',
  Studio = 'Studio'
}

export enum VideoMode {
  Similar = 'similar',
  Different = 'different'
}

export interface PromptRow {
  stt: number;
  prompt: string;
  voice: string;
}

export interface VideoConfig {
  summary: string;
  styleAnalysis: string;
  mode: VideoMode;
  topic: string;
  visualStyle: VisualStyle;
  aspectRatio: '16:9' | '9:16';
  durationMin: number;
  voiceLang: string;
  channelName: string;
  background: string;
  timeline: string;
  prompts: PromptRow[];
}

import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;
  private modelName = 'gemini-3-flash-preview';

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  async verifyKey() {
    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: "Say 'OK' if you can hear me.",
        config: { maxOutputTokens: 5 }
      });
      return !!response.text;
    } catch (error: any) {
      if (error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED')) {
        throw new Error('QUOTA_EXHAUSTED');
      }
      throw new Error('INVALID_KEY');
    }
  }

  async generateTopic(summary: string, style: string, mode: string): Promise<string> {
    const prompt = `Bạn là một chuyên gia biên kịch video.
    Dựa trên nội dung: "${summary}" và phong cách: "${style}".
    Chế độ: ${mode === 'similar' ? 'Tạo video tương tự (cùng trục nội dung nhưng viết mới, hay hơn, không sao chép)' : 'Tạo chủ đề khác biệt (chủ đề mới hoàn toàn nhưng vẫn hợp phong cách/cấu trúc)'}.
    Hãy đề xuất 1 câu tiêu đề/chủ đề mới hấp dẫn. Chỉ trả về đúng 1 câu chủ đề, không thêm giải thích.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text || '';
  }

  async generateBackground(topic: string, visualStyle: string, styleAnalysis: string): Promise<string> {
    const prompt = `Dựa trên chủ đề mới: "${topic}", phong cách hình ảnh: "${visualStyle}" và phân tích phong cách: "${styleAnalysis}".
    Hãy mô tả 1-2 câu bối cảnh/nền tảng phù hợp cho video này. Trả về văn bản thuần túy.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text || '';
  }

  async generateTimeline(topic: string, background: string, durationSec: number, styleAnalysis: string): Promise<string> {
    const prompt = `Tạo dàn ý chi tiết cho video chủ đề: "${topic}".
    Thời lượng thực tế: ${durationSec} giây.
    Bối cảnh: "${background}".
    Phong cách phân tích: "${styleAnalysis}".

    YÊU CẦU ĐỊNH DẠNG (BẮT BUỘC):
    - Tiêu đề: "DÀN Ý CHI TIẾT: ${topic} (${durationSec} GIÂY)"
    - Chia video thành 4-8 PHẦN.
    - Mỗi PHẦN phải có định dạng:
      PHẦN [Số]: [Tên phần] (Phút [bắt đầu] - Phút [kết thúc])
      1) Bối cảnh: [Mô tả bối cảnh]
      2) Hình ảnh: (Liệt kê Cảnh 1, Cảnh 2... có time nhỏ bên trong, ví dụ: Cảnh 1 (0:00 - 0:08): ...)
      3) Âm thanh: [Nhạc nền, hiệu ứng]
      4) Nội dung lời dẫn/Text: [Nội dung chính]

    - Đảm bảo tổng thời gian từ 0:00 đến đúng ${durationSec} giây.
    - Logic: Intro/Hook -> Nội dung chính -> Outro.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text || '';
  }

  async generatePrompts(timeline: string, background: string, visualStyle: string, aspectRatio: string, N: number, voiceLang: string): Promise<any[]> {
    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: `Dựa trên dàn ý video sau đây:
      ${timeline}

      Bối cảnh nền: ${background}
      Phong cách: ${visualStyle}, Định dạng: ${aspectRatio}
      Số đoạn (8 giây mỗi đoạn): ${N}
      Ngôn ngữ Voice: ${voiceLang}

      Nhiệm vụ: Tạo bảng 3 cột cho ${N} đoạn video, mỗi đoạn chính xác 8 giây.
      Cột 1: STT (1 đến ${N})
      Cột 2: PROMPT (TIẾNG ANH) - Mô tả hình ảnh chi tiết cho AI tạo video (chứa Visual Style, Aspect Ratio, Bối cảnh, Action, Camera shot, Lighting. Thêm "Negative: blurry, jitter, distorted hands, text artifacts, watermark" ở cuối mỗi prompt).
      Cột 3: VOICE (Tiếng ${voiceLang}) - 1 câu thoại ngắn gọn, súc tích đọc vừa đủ trong ~8 giây (Tiếng Việt khoảng 18-25 từ, Tiếng Anh 20-28 từ).

      Trả về định dạng JSON array của các object { "stt": number, "prompt": string, "voice": string }.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              stt: { type: Type.NUMBER },
              prompt: { type: Type.STRING },
              voice: { type: Type.STRING }
            },
            required: ["stt", "prompt", "voice"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse JSON prompts", e);
      return [];
    }
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GeminiService } from './services/geminiService';
import { VideoConfig, VideoMode, VisualStyle, PromptRow } from './types';

// Helper components
const Button: React.FC<{ 
  onClick?: () => void; 
  disabled?: boolean; 
  className?: string; 
  loading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  children: React.ReactNode;
}> = ({ onClick, disabled, className = '', loading, variant = 'primary', children }) => {
  const baseStyles = "px-6 py-2.5 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-gray-700 hover:bg-gray-600 text-white border border-gray-600",
    danger: "bg-red-600 hover:bg-red-700 text-white",
    ghost: "bg-transparent hover:bg-gray-800 text-gray-300"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled || loading} 
      className={`${baseStyles} ${variants[variant]} ${className}`}
    >
      {loading ? <i className="fas fa-spinner fa-spin"></i> : children}
    </button>
  );
};

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
  <div className={`bg-gray-800/50 border border-gray-700 rounded-xl p-6 ${className}`}>
    <h3 className="text-lg font-semibold mb-4 text-blue-400 flex items-center gap-2">
      <div className="w-1 h-6 bg-blue-500 rounded-full"></div>
      {title}
    </h3>
    {children}
  </div>
);

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => {
  const steps = ["Khởi đầu", "Nhập liệu", "Cấu hình", "Dàn ý", "Prompt"];
  return (
    <div className="flex items-center justify-between mb-8 max-w-4xl mx-auto px-4">
      {steps.map((step, idx) => (
        <React.Fragment key={idx}>
          <div className="flex flex-col items-center relative z-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all ${
              idx <= currentStep ? "bg-blue-600 border-blue-600 text-white" : "border-gray-700 text-gray-500 bg-gray-900"
            }`}>
              {idx < currentStep ? <i className="fas fa-check text-sm"></i> : idx + 1}
            </div>
            <span className={`text-xs mt-2 font-medium ${idx <= currentStep ? "text-blue-400" : "text-gray-500"}`}>
              {step}
            </span>
          </div>
          {idx < steps.length - 1 && (
            <div className={`flex-1 h-0.5 mx-2 ${idx < currentStep ? "bg-blue-600" : "bg-gray-700"}`}></div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
};

export default function App() {
  const [step, setStep] = useState(0);
  const [apiKey, setApiKey] = useState('');
  const [isApiKeyVerified, setIsApiKeyVerified] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [config, setConfig] = useState<VideoConfig>({
    summary: '',
    styleAnalysis: '',
    mode: VideoMode.Similar,
    topic: '',
    visualStyle: VisualStyle.Cinematic,
    aspectRatio: '16:9',
    durationMin: 1,
    voiceLang: 'Tiếng Việt',
    channelName: '',
    background: '',
    timeline: '',
    prompts: []
  });

  const gemini = useMemo(() => new GeminiService(apiKey), [apiKey]);

  const handleVerifyKey = async () => {
    setLoading(true);
    setError(null);
    try {
      await gemini.verifyKey();
      setIsApiKeyVerified(true);
      setStep(1);
    } catch (err: any) {
      if (err.message === 'QUOTA_EXHAUSTED') {
        setError("API Key đã hết quota. Vui lòng nhập API key khác để tiếp tục.");
      } else {
        setError("API Key không hợp lệ. Vui lòng nhập lại.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleApiError = useCallback((err: any) => {
    if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
      setError("Hết quota API! Vui lòng cập nhật API key mới.");
      setStep(0);
      setIsApiKeyVerified(false);
    } else {
      setError(err.message || "Đã xảy ra lỗi không xác định.");
    }
  }, []);

  const nextStep = () => setStep(prev => prev + 1);
  const prevStep = () => setStep(prev => prev - 1);

  // --- Step 2 Logic ---
  const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
  const numSegments = Math.ceil(config.durationMin * 60 / 8);

  const generateAITopic = async () => {
    setLoading(true);
    try {
      const topic = await gemini.generateTopic(config.summary, config.styleAnalysis, config.mode);
      const bg = await gemini.generateBackground(topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, topic, background: bg }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const regenerateBackground = async () => {
    setLoading(true);
    try {
      const bg = await gemini.generateBackground(config.topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, background: bg }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  // --- Step 3 Logic ---
  const generateTimeline = async () => {
    setLoading(true);
    try {
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  // --- Step 4 Logic ---
  const generatePrompts = async () => {
    setLoading(true);
    try {
      const prompts = await gemini.generatePrompts(
        config.timeline, 
        config.background, 
        config.visualStyle, 
        config.aspectRatio, 
        numSegments, 
        config.voiceLang
      );
      setConfig(prev => ({ ...prev, prompts }));
      nextStep();
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const copyPromptsToClipboard = () => {
    const text = config.prompts.map(p => `STT: ${p.stt}\nPROMPT: ${p.prompt}\nVOICE: ${p.voice}\n---`).join('\n');
    navigator.clipboard.writeText(text);
    alert('Đã copy toàn bộ prompt vào clipboard!');
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 py-4 px-6 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <i className="fas fa-magic text-white"></i>
            </div>
            <h1 className="text-xl font-bold tracking-tight">AI Video Wizard <span className="text-blue-500">v2.0</span></h1>
          </div>
          {isApiKeyVerified && (
            <div className="flex items-center gap-2 text-sm text-green-400 bg-green-900/20 px-3 py-1.5 rounded-full border border-green-800">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              API Connected
            </div>
          )}
        </div>
      </header>

      <main className="max-w-5xl mx-auto mt-8 px-4">
        {step > 0 && <StepIndicator currentStep={step} />}

        {error && (
          <div className="bg-red-900/30 border border-red-800 text-red-200 px-4 py-3 rounded-lg mb-6 flex items-center gap-3">
            <i className="fas fa-exclamation-circle"></i>
            {error}
            <button onClick={() => setError(null)} className="ml-auto text-red-400 hover:text-red-300">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}

        {/* STEP 0: API KEY */}
        {step === 0 && (
          <div className="max-w-md mx-auto mt-20">
            <Card title="Xác thực API Key">
              <p className="text-gray-400 text-sm mb-4">Nhập Gemini API Key của bạn để bắt đầu sử dụng tất cả tính năng.</p>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Google Gemini API Key</label>
                  <input 
                    type="password" 
                    placeholder="Dán API Key tại đây..." 
                    value={apiKey}
                    onChange={(e) => setApiKey(e.target.value)}
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-600 outline-none"
                  />
                </div>
                <Button onClick={handleVerifyKey} loading={loading} className="w-full">
                  Kiểm tra API <i className="fas fa-arrow-right"></i>
                </Button>
                <p className="text-center text-xs text-gray-500">
                  <a href="https://aistudio.google.com/app/apikey" target="_blank" className="hover:text-blue-400 underline">Lấy API Key miễn phí tại đây</a>
                </p>
              </div>
            </Card>
          </div>
        )}

        {/* STEP 1: SUMMARY & STYLE */}
        {step === 1 && (
          <div className="grid md:grid-cols-2 gap-6">
            <Card title="Tóm tắt nội dung">
              <textarea 
                className="w-full bg-gray-900 border border-gray-700 rounded-lg p-4 h-64 focus:ring-2 focus:ring-blue-600 outline-none resize-none custom-scrollbar"
                placeholder="Ví dụ: Video hướng dẫn làm bánh mì Việt Nam giòn tan tại nhà..."
                value={config.summary}
                onChange={(e) => setConfig(prev => ({ ...prev, summary: e.target.value }))}
              />
            </Card>
            <Card title="Phân tích phong cách">
              <textarea 
                className="w-full bg-gray-900 border border-gray-700 rounded-lg p-4 h-64 focus:ring-2 focus:ring-blue-600 outline-none resize-none custom-scrollbar"
                placeholder="Ví dụ: Nhịp điệu nhanh, âm nhạc lo-fi, tông màu ấm áp, quay cận cảnh..."
                value={config.styleAnalysis}
                onChange={(e) => setConfig(prev => ({ ...prev, styleAnalysis: e.target.value }))}
              />
            </Card>
            <div className="md:col-span-2 grid grid-cols-2 gap-4">
               <div 
                onClick={() => setConfig(prev => ({ ...prev, mode: VideoMode.Similar }))}
                className={`cursor-pointer p-4 rounded-xl border-2 transition-all ${config.mode === VideoMode.Similar ? "border-blue-600 bg-blue-900/20" : "border-gray-700 bg-gray-800/40 hover:border-gray-600"}`}
               >
                 <div className="flex items-center gap-3 mb-2">
                   <div className={`w-5 h-5 rounded-full border-4 ${config.mode === VideoMode.Similar ? "border-blue-500" : "border-gray-600"}`}></div>
                   <h4 className="font-bold">Tạo Video Tương Tự</h4>
                 </div>
                 <p className="text-xs text-gray-400">Cùng trục nội dung nhưng viết mới, hay hơn, tránh trùng lặp.</p>
               </div>
               <div 
                onClick={() => setConfig(prev => ({ ...prev, mode: VideoMode.Different }))}
                className={`cursor-pointer p-4 rounded-xl border-2 transition-all ${config.mode === VideoMode.Different ? "border-blue-600 bg-blue-900/20" : "border-gray-700 bg-gray-800/40 hover:border-gray-600"}`}
               >
                 <div className="flex items-center gap-3 mb-2">
                   <div className={`w-5 h-5 rounded-full border-4 ${config.mode === VideoMode.Different ? "border-blue-500" : "border-gray-600"}`}></div>
                   <h4 className="font-bold">Tạo Chủ Đề Khác Biệt</h4>
                 </div>
                 <p className="text-xs text-gray-400">Chủ đề hoàn toàn mới nhưng vẫn giữ phong cách và cấu trúc.</p>
               </div>
            </div>
            <div className="md:col-span-2 flex justify-end">
              <Button onClick={nextStep} disabled={!config.summary || !config.styleAnalysis}>Tiếp tục</Button>
            </div>
          </div>
        )}

        {/* STEP 2: CONFIGURATION */}
        {step === 2 && (
          <div className="space-y-6">
            <Card title="Chủ đề & Bối cảnh">
              <div className="space-y-4">
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-sm font-medium text-gray-300">Chủ đề mới muốn làm</label>
                    <button onClick={generateAITopic} disabled={loading} className="text-blue-400 text-xs hover:text-blue-300">
                      <i className="fas fa-magic mr-1"></i> {config.topic ? "Gợi ý khác (AI)" : "AI Tự tạo chủ đề"}
                    </button>
                  </div>
                  <textarea 
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-3 h-20 outline-none"
                    value={config.topic}
                    onChange={(e) => setConfig(prev => ({ ...prev, topic: e.target.value }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-sm font-medium text-gray-300">Bối cảnh / Nền tảng (AI sinh)</label>
                    <button onClick={regenerateBackground} disabled={loading || !config.topic} className="text-blue-400 text-xs hover:text-blue-300">
                      <i className="fas fa-sync mr-1"></i> Tạo lại bối cảnh (AI)
                    </button>
                  </div>
                  <textarea 
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-3 h-24 outline-none"
                    value={config.background}
                    onChange={(e) => setConfig(prev => ({ ...prev, background: e.target.value }))}
                  />
                </div>
              </div>
            </Card>

            <div className="grid md:grid-cols-2 gap-6">
              <Card title="Phong cách hình ảnh">
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(VisualStyle).map(v => (
                    <button 
                      key={v}
                      onClick={() => setConfig(prev => ({ ...prev, visualStyle: v }))}
                      className={`py-2 px-3 rounded-lg text-sm transition-all border ${config.visualStyle === v ? "bg-blue-600 border-blue-600" : "bg-gray-900 border-gray-700 hover:border-gray-600"}`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </Card>

              <Card title="Định dạng & Thời lượng">
                <div className="space-y-4">
                  <div className="flex gap-4">
                    <button 
                      onClick={() => setConfig(prev => ({ ...prev, aspectRatio: '16:9' }))}
                      className={`flex-1 py-2 rounded-lg border flex items-center justify-center gap-2 ${config.aspectRatio === '16:9' ? "bg-blue-600 border-blue-600" : "bg-gray-900 border-gray-700"}`}
                    >
                      <i className="fas fa-desktop"></i> 16:9
                    </button>
                    <button 
                      onClick={() => setConfig(prev => ({ ...prev, aspectRatio: '9:16' }))}
                      className={`flex-1 py-2 rounded-lg border flex items-center justify-center gap-2 ${config.aspectRatio === '9:16' ? "bg-blue-600 border-blue-600" : "bg-gray-900 border-gray-700"}`}
                    >
                      <i className="fas fa-mobile-alt"></i> 9:16
                    </button>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="flex-1">
                      <label className="text-xs text-gray-500 uppercase font-bold">Thời lượng (phút)</label>
                      <input 
                        type="number" step="0.5" min="0.5" max="30"
                        className="w-full bg-gray-900 border border-gray-700 rounded-lg px-3 py-2 outline-none mt-1"
                        value={config.durationMin}
                        onChange={(e) => setConfig(prev => ({ ...prev, durationMin: parseFloat(e.target.value) }))}
                      />
                    </div>
                    <div className="flex-1 bg-gray-900/50 p-2 rounded-lg border border-gray-800">
                      <p className="text-[10px] text-gray-500 uppercase font-bold">Thống kê</p>
                      <p className="text-xs text-blue-400">Số đoạn 8s: <span className="font-bold">{numSegments}</span></p>
                      <p className="text-xs text-blue-400">Thực tế: <span className="font-bold">{durationSecActual}s</span> (~{(durationSecActual/60).toFixed(1)}p)</p>
                    </div>
                  </div>
                </div>
              </Card>
            </div>

            <Card title="Cấu hình khác">
               <div className="grid md:grid-cols-2 gap-4">
                 <div>
                   <label className="text-xs text-gray-500 uppercase font-bold">Ngôn ngữ Voice</label>
                   <select 
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg px-3 py-2 outline-none mt-1"
                    value={config.voiceLang}
                    onChange={(e) => setConfig(prev => ({ ...prev, voiceLang: e.target.value }))}
                   >
