                    placeholder="Tên kênh của bạn..."
                    value={config.channelName}
                    onChange={(e) => setConfig(prev => ({ ...prev, channelName: e.target.value }))}
                   />
                 </div>
               </div>
            </Card>

            <div className="flex justify-between">
              <Button variant="secondary" onClick={prevStep}>Quay lại</Button>
              <Button onClick={nextStep} disabled={!config.topic || loading}>Tiếp tục</Button>
            </div>
          </div>
        )}

        {/* STEP 3: TIMELINE */}
        {step === 3 && (
          <div className="space-y-6">
            <Card title={`DÀN Ý CHI TIẾT: ${config.topic} (${durationSecActual} GIÂY)`}>
              <div className="mb-4 bg-blue-900/20 border border-blue-800/50 p-3 rounded-lg text-sm text-blue-200">
                <i className="fas fa-info-circle mr-2"></i>
                Kiểm tra và chỉnh sửa dàn ý chi tiết bên dưới. Đảm bảo logic từng phút trước khi tiếp tục tạo Prompt.
              </div>
              <textarea 
                className="w-full bg-gray-900 border border-gray-700 rounded-lg p-4 h-[500px] focus:ring-2 focus:ring-blue-600 outline-none resize-none custom-scrollbar font-mono text-sm leading-relaxed"
                value={config.timeline}
                onChange={(e) => setConfig(prev => ({ ...prev, timeline: e.target.value }))}
