              </div>
            </Card>

            <div className="flex justify-between">
              <Button variant="secondary" onClick={prevStep}>Quay lại</Button>
              <Button onClick={generatePrompts} disabled={!config.timeline || loading}>Tiếp tục tạo Prompt</Button>
            </div>
          </div>
        )}

        {/* STEP 4: FINAL PROMPTS */}
        {step === 4 && (
          <div className="space-y-6">
            <div className="flex justify-between items-center bg-gray-800 p-4 rounded-xl border border-gray-700">
               <div>
                 <h2 className="text-xl font-bold">Kết quả cuối cùng</h2>
                 <p className="text-gray-400 text-sm">Timeline và Bảng Prompt đã sẵn sàng.</p>
               </div>
               <Button onClick={copyPromptsToClipboard} variant="primary">
                 <i className="fas fa-copy"></i> Copy toàn bộ Prompt
               </Button>
            </div>

            <div className="flex gap-4 border-b border-gray-800 mb-4">
              <button className="px-6 py-3 border-b-2 border-blue-600 text-blue-400 font-bold text-sm">BẢNG PROMPT</button>
              <button onClick={() => setStep(3)} className="px-6 py-3 text-gray-500 hover:text-gray-300 font-bold text-sm">XEM LẠI TIMELINE</button>
            </div>

            <div className="bg-gray-800 border border-gray-700 rounded-xl overflow-hidden overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="bg-gray-900/50 border-b border-gray-700 text-gray-400 uppercase text-[10px] font-bold tracking-widest">
                  <tr>
                    <th className="px-6 py-4 w-16">STT</th>
                    <th className="px-6 py-4">VIDEO PROMPT (TIẾNG ANH)</th>
                    <th className="px-6 py-4 w-1/3">VOICE ({config.voiceLang})</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-700">
                  {config.prompts.length > 0 ? config.prompts.map((p, idx) => (
                    <tr key={idx} className="hover:bg-gray-700/30 transition-colors">
                      <td className="px-6 py-4 font-mono text-blue-400 font-bold">{p.stt}</td>
                      <td className="px-6 py-4">
                        <div className="bg-gray-900/50 p-3 rounded border border-gray-700 italic text-gray-300 leading-relaxed">
                          {p.prompt}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-blue-100 font-medium">
                          {p.voice}
                        </div>
                      </td>
                    </tr>
                  )) : (
                    <tr>
                      <td colSpan={3} className="px-6 py-20 text-center text-gray-500 italic">
                        Chưa có dữ liệu prompt...
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>

            <div className="flex justify-between">
              <Button variant="secondary" onClick={prevStep}>Quay lại chỉnh sửa</Button>
              <Button variant="danger" onClick={() => { if(confirm("Xác nhận làm mới toàn bộ?")) window.location.reload(); }}>
                 <i className="fas fa-trash"></i> Làm lại từ đầu
              </Button>
            </div>
          </div>
        )}
      </main>

      {/* Floating Action Hint */}
      {loading && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-blue-600 text-white px-6 py-3 rounded-full shadow-2xl z-[60] flex items-center gap-3 animate-bounce">
          <i className="fas fa-circle-notch fa-spin"></i>
          <span className="font-bold">AI đang xử lý, vui lòng đợi...</span>
        </div>
      )}
    </div>
  );
}

