import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;
  private modelName = 'gemini-3-flash-preview';

  constructor() {
    // API Key must be obtained exclusively from process.env.API_KEY
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  async verifyKey() {
    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: "Kiểm tra hệ thống. Trả lời 'OK'.",
        config: { maxOutputTokens: 10 }
      });
      return !!response.text;
    } catch (error: any) {
      console.error("API Verification Error:", error);
      if (error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED')) {
        throw new Error('QUOTA_EXHAUSTED');
      }
      throw new Error('INVALID_KEY');
    }
  }

  async generateTopic(summary: string, style: string, mode: string): Promise<string> {
    const prompt = `Bạn là một chuyên gia biên kịch video chuyên nghiệp.
    Dựa trên tóm tắt nội dung: "${summary}" và phong cách: "${style}".
    Chế độ: ${mode === 'similar' ? 'Tạo video tương tự (cùng trục nội dung nhưng viết mới, hay hơn, không sao chép)' : 'Tạo chủ đề khác biệt (chủ đề mới hoàn toàn nhưng vẫn hợp phong cách/cấu trúc)'}.
    Hãy đề xuất 1 câu tiêu đề/chủ đề mới cực kỳ hấp dẫn. Chỉ trả về đúng 1 câu chủ đề, không thêm bất kỳ giải thích nào.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text?.trim() || '';
  }

  async generateBackground(topic: string, visualStyle: string, styleAnalysis: string): Promise<string> {
    const prompt = `Dựa trên chủ đề: "${topic}", phong cách hình ảnh: "${visualStyle}" và phân tích phong cách: "${styleAnalysis}".
    Hãy mô tả 1-2 câu bối cảnh/nền tảng phù hợp nhất cho video này. Trả về văn bản thuần túy, súc tích.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text?.trim() || '';
  }

  async generateTimeline(topic: string, background: string, durationSec: number, styleAnalysis: string): Promise<string> {
    const prompt = `Tạo dàn ý chi tiết cho video.
    Chủ đề: "${topic}"
    Thời lượng: ${durationSec} giây.
    Bối cảnh: "${background}"
    Phong cách: "${styleAnalysis}"

    YÊU CẦU ĐỊNH DẠNG (BẮT BUỘC ĐÚNG STYLE):
    - Tiêu đề: "DÀN Ý CHI TIẾT: ${topic.toUpperCase()} (${durationSec} GIÂY)"
    - Chia video thành các PHẦN (ví dụ PHẦN 1, PHẦN 2...).
    - Mỗi PHẦN bắt buộc có định dạng:
      PHẦN [Số]: [Tên phần] (Phút [bắt đầu] - Phút [kết thúc])
      1) Bối cảnh: [Mô tả]
      2) Hình ảnh: (Liệt kê Cảnh 1, Cảnh 2... kèm mốc thời gian nhỏ, ví dụ: Cảnh 1 (0:00 - 0:08): ...)
      3) Âm thanh: [Nhạc, SFX]
      4) Nội dung lời dẫn/Text: [Script]

    - Đảm bảo tổng thời gian từ 0:00 đến đúng mốc ${durationSec} giây.
    - Cấu trúc: Hook -> Nội dung chính -> Kết nối -> Outro.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt
    });
    return response.text || '';
  }

  async generatePrompts(timeline: string, background: string, visualStyle: string, aspectRatio: string, N: number, voiceLang: string): Promise<any[]> {
    const prompt = `Dựa trên dàn ý video chi tiết:
    ${timeline}

    Thông tin bổ sung:
    - Bối cảnh: ${background}
    - Visual Style: ${visualStyle}
    - Tỷ lệ khung hình: ${aspectRatio}
    - Ngôn ngữ Voice: ${voiceLang}
    - Tổng số đoạn 8s cần tạo: ${N}

    NHIỆM VỤ: Tạo bảng 3 cột cho đúng ${N} đoạn (mỗi đoạn 8 giây).
    Cột 1: STT (từ 1 đến ${N})
    Cột 2: PROMPT (TIẾNG ANH) - Mô tả chi tiết cho AI Video (D-ID, Sora, Runway style). Phải bao gồm: ${visualStyle}, ${aspectRatio}, action cụ thể, camera movement (pan, tilt, zoom), lighting. Cuối mỗi prompt LUÔN thêm: "Negative: blurry, low resolution, jitter, distorted face, watermark, text artifacts".
    Cột 3: VOICE (Tiếng ${voiceLang}) - Một câu thoại vừa đủ đọc trong khoảng 8 giây (khoảng 20-25 từ cho Tiếng Việt).

    Trả về JSON array các object: { "stt": number, "prompt": string, "voice": string }.`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              stt: { type: Type.NUMBER },
              prompt: { type: Type.STRING },
              voice: { type: Type.STRING }
            },
            required: ["stt", "prompt", "voice"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Prompt Parsing Error:", e);
      return [];
    }
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GeminiService } from './services/geminiService';
import { VideoConfig, VideoMode, VisualStyle, PromptRow } from './types';

// Helper components
const Button: React.FC<{ 
  onClick?: () => void; 
  disabled?: boolean; 
  className?: string; 
  loading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'success';
  children: React.ReactNode;
}> = ({ onClick, disabled, className = '', loading, variant = 'primary', children }) => {
  const baseStyles = "px-6 py-2.5 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-gray-700 hover:bg-gray-600 text-white border border-gray-600",
    danger: "bg-red-600 hover:bg-red-700 text-white",
    success: "bg-emerald-600 hover:bg-emerald-700 text-white",
    ghost: "bg-transparent hover:bg-gray-800 text-gray-300"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled || loading} 
      className={`${baseStyles} ${variants[variant]} ${className}`}
    >
      {loading ? <i className="fas fa-spinner fa-spin"></i> : children}
    </button>
  );
};

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
  <div className={`bg-gray-800/50 border border-gray-700 rounded-xl p-6 shadow-xl backdrop-blur-sm ${className}`}>
    <h3 className="text-lg font-semibold mb-4 text-blue-400 flex items-center gap-2">
      <div className="w-1.5 h-6 bg-blue-500 rounded-full"></div>
      {title}
    </h3>
    {children}
  </div>
);

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => {
  const steps = ["Hệ thống", "Nội dung", "Cấu hình", "Dàn ý", "Hoàn tất"];
  return (
    <div className="flex items-center justify-between mb-10 max-w-4xl mx-auto px-4">
      {steps.map((step, idx) => (
        <React.Fragment key={idx}>
          <div className="flex flex-col items-center relative z-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${
              idx <= currentStep ? "bg-blue-600 border-blue-600 text-white scale-110 shadow-lg shadow-blue-900/40" : "border-gray-700 text-gray-500 bg-gray-900"
            }`}>
              {idx < currentStep ? <i className="fas fa-check text-sm"></i> : idx + 1}
            </div>
            <span className={`text-[10px] uppercase tracking-wider mt-3 font-bold ${idx <= currentStep ? "text-blue-400" : "text-gray-600"}`}>
              {step}
            </span>
          </div>
          {idx < steps.length - 1 && (
            <div className={`flex-1 h-0.5 mx-2 rounded-full transition-all duration-700 ${idx < currentStep ? "bg-blue-600" : "bg-gray-800"}`}></div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
};

export default function App() {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSystemReady, setIsSystemReady] = useState(false);

  const [config, setConfig] = useState<VideoConfig>({
    summary: '',
    styleAnalysis: '',
    mode: VideoMode.Similar,
    topic: '',
    visualStyle: VisualStyle.Cinematic,
    aspectRatio: '16:9',
    durationMin: 1,
    voiceLang: 'Tiếng Việt',
    channelName: '',
    background: '',
    timeline: '',
    prompts: []
  });

  const gemini = useMemo(() => new GeminiService(), []);

  // Step 0: System verification
  useEffect(() => {
    if (step === 0) {
      const init = async () => {
        setLoading(true);
        try {
          await gemini.verifyKey();
          setIsSystemReady(true);
          setTimeout(() => setStep(1), 800);
        } catch (err: any) {
          if (err.message === 'QUOTA_EXHAUSTED') {
            setError("Hệ thống hiện đang quá tải (Quota Exhausted). Vui lòng thử lại sau giây lát.");
          } else {
            setError("Lỗi kết nối API. Vui lòng kiểm tra cấu hình hệ thống.");
          }
        } finally {
          setLoading(false);
        }
      };
      init();
    }
  }, [step, gemini]);

  const handleApiError = useCallback((err: any) => {
    console.error("API Error caught:", err);
    if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
      setError("Cảnh báo: Hết Quota API. Quá trình tạo nội dung bị tạm dừng.");
    } else {
      setError(err.message || "Đã xảy ra lỗi không xác định trong quá trình xử lý.");
    }
  }, []);

  const nextStep = () => setStep(prev => prev + 1);
  const prevStep = () => setStep(prev => prev - 1);

  const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
  const numSegments = Math.ceil(config.durationMin * 60 / 8);

  const generateAITopic = async () => {
    setLoading(true);
    setError(null);
    try {
      const topic = await gemini.generateTopic(config.summary, config.styleAnalysis, config.mode);
      const bg = await gemini.generateBackground(topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, topic, background: bg }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const regenerateBackground = async () => {
    setLoading(true);
    setError(null);
    try {
      const bg = await gemini.generateBackground(config.topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, background: bg }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const generateTimeline = async () => {
    setLoading(true);
    setError(null);
    try {
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const generatePrompts = async () => {
    setLoading(true);
    setError(null);
    try {
      const prompts = await gemini.generatePrompts(
        config.timeline, 
        config.background, 
        config.visualStyle, 
        config.aspectRatio, 
        numSegments, 
        config.voiceLang
      );
      setConfig(prev => ({ ...prev, prompts }));
      nextStep();
    } catch (err) {
      handleApiError(err);
    } finally {
      setLoading(false);
    }
  };

  const copyPromptsToClipboard = () => {
    const text = config.prompts.map(p => `STT: ${p.stt}\nPROMPT: ${p.prompt}\nVOICE: ${p.voice}\n---`).join('\n');
    navigator.clipboard.writeText(text);
    alert('Đã copy toàn bộ bảng prompt vào clipboard!');
  };

  return (
    <div className="min-h-screen pb-20 bg-[#0b1120]">
      {/* Header */}
      <header className="bg-gray-900/80 backdrop-blur-md border-b border-gray-800 py-4 px-6 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-blue-500 to-indigo-600 p-2 rounded-lg shadow-lg">
              <i className="fas fa-film text-white"></i>
            </div>
            <h1 className="text-xl font-extrabold tracking-tight">AI VIDEO <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-indigo-400">WIZARD</span></h1>
          </div>
          {isSystemReady && (
            <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-emerald-400 bg-emerald-950/30 px-4 py-2 rounded-full border border-emerald-800/50">
              <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
              Gemini Engine Online
            </div>
          )}
        </div>
      </header>

      <main className="max-w-5xl mx-auto mt-10 px-4">
        <StepIndicator currentStep={step} />

        {error && (
          <div className="bg-red-950/40 border border-red-800/50 text-red-200 px-5 py-4 rounded-xl mb-8 flex items-start gap-4 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
            <i className="fas fa-triangle-exclamation text-red-500 mt-1"></i>
            <div className="flex-1">
              <p className="font-bold text-sm uppercase mb-1">Cảnh báo hệ thống</p>
              <p className="text-sm opacity-90">{error}</p>
            </div>
            <button onClick={() => setError(null)} className="text-red-400 hover:text-red-300 transition-colors">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}

        {/* STEP 0: INITIALIZATION */}
        {step === 0 && (
          <div className="flex flex-col items-center justify-center mt-32 space-y-6">
            <div className="relative">
              <div className="w-20 h-20 border-4 border-blue-900/30 border-t-blue-500 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <i className="fas fa-microchip text-blue-500 animate-pulse"></i>
              </div>
            </div>
            <div className="text-center">
              <h2 className="text-xl font-bold text-white mb-2">Đang khởi tạo hệ thống...</h2>
              <p className="text-gray-500 text-sm">Vui lòng chờ trong khi AI Video Wizard kiểm tra cấu hình API.</p>
            </div>
          </div>
        )}

        {/* STEP 1: SUMMARY & STYLE */}
        {step === 1 && (
          <div className="grid md:grid-cols-2 gap-8 animate-in fade-in duration-500">
            <Card title="Tóm tắt nội dung video">
              <textarea 
                className="w-full bg-gray-900/80 border border-gray-700 rounded-xl p-4 h-72 focus:ring-2 focus:ring-blue-600 outline-none resize-none custom-scrollbar transition-all font-medium text-gray-200 placeholder:text-gray-600"
                placeholder="Ví dụ: Video chia sẻ công thức nấu phở bò chuẩn vị Hà Nội tại nhà cho người mới bắt đầu..."
                value={config.summary}
                onChange={(e) => setConfig(prev => ({ ...prev, summary: e.target.value }))}
              />
            </Card>
            <Card title="Phân tích phong cách">
              <textarea 
                className="w-full bg-gray-900/80 border border-gray-700 rounded-xl p-4 h-72 focus:ring-2 focus:ring-blue-600 outline-none resize-none custom-scrollbar transition-all font-medium text-gray-200 placeholder:text-gray-600"
                placeholder="Ví dụ: Cinematic, slow-motion, âm thanh tiếng dao thái sần sật, nhạc không lời êm dịu, tông màu hơi hướng cổ điển..."
                value={config.styleAnalysis}
                onChange={(e) => setConfig(prev => ({ ...prev, styleAnalysis: e.target.value }))}
              />
            </Card>
            <div className="md:col-span-2 grid grid-cols-2 gap-6">
