      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 py-4 px-6 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg">
              <i className="fas fa-bolt text-white"></i>
            </div>
            <h1 className="text-xl font-black tracking-tighter">VIDEO WIZARD <span className="text-blue-500">AI</span></h1>
          </div>
          {isSystemReady && (
