import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;
  private modelName = 'gemini-3-flash-preview';

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  async verifyKey() {
    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: "Check system. Reply 'OK'.",
        config: { maxOutputTokens: 5 }
      });
      return !!response.text;
    } catch (error: any) {
      if (error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED')) {
        throw new Error('QUOTA_EXHAUSTED');
      }
      throw new Error('INVALID_KEY');
    }
  }

  async generateInitialSetup(summary: string, style: string, mode: string, visualStyle: string): Promise<{topic: string, background: string}> {
    const prompt = `Bạn là chuyên gia tư vấn nội dung video. 
    Nội dung gốc: "${summary}"
    Phong cách gốc: "${style}"
    Visual Style: "${visualStyle}"
    Chế độ: ${mode === 'similar' ? 'Tạo tương tự (giữ trục nội dung, viết mới hay hơn)' : 'Tạo khác biệt (Chủ đề mới hoàn toàn, tránh bản quyền, nhưng cùng phong cách)'}

    NHIỆM VỤ: 
    1. Tạo 1 câu "Chủ đề mới muốn làm" (hấp dẫn, chuẩn viral).
    2. Tạo 1-2 câu "Bối cảnh/Nền tảng" phù hợp nhất với chủ đề mới đó.

    Trả về định dạng JSON: { "topic": "string", "background": "string" }`;

    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt,
      config: { 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            topic: { type: Type.STRING },
            background: { type: Type.STRING }
          },
          required: ["topic", "background"]
        }
      }
    });

    try {
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return { topic: "Lỗi tạo chủ đề", background: "Lỗi tạo bối cảnh" };
    }
  }

  async generateTopic(summary: string, style: string, mode: string): Promise<string> {
    const prompt = `Đề xuất 1 câu tiêu đề/chủ đề video mới dựa trên: 
    Nội dung: "${summary}"
    Phong cách: "${style}"
    Chế độ: ${mode === 'similar' ? 'Tương tự' : 'Khác biệt hoàn toàn'}. 
    Chỉ trả về 1 câu duy nhất.`;
    const response = await this.ai.models.generateContent({ model: this.modelName, contents: prompt });
    return response.text?.trim() || '';
  }

  async generateBackground(topic: string, visualStyle: string, styleAnalysis: string): Promise<string> {
    const prompt = `Dựa trên chủ đề: "${topic}", Visual Style: "${visualStyle}" và Phong cách: "${styleAnalysis}".
    Hãy mô tả 1-2 câu bối cảnh/nền tảng của video này. Trả về văn bản thuần túy.`;
    const response = await this.ai.models.generateContent({ model: this.modelName, contents: prompt });
    return response.text?.trim() || '';
  }

  async generateTimeline(topic: string, background: string, durationSec: number, styleAnalysis: string): Promise<string> {
    const prompt = `Bạn là một biên kịch chuyên nghiệp. Hãy tạo dàn ý chi tiết cho video.

    THÔNG TIN ĐẦU VÀO:
    - Chủ đề: "${topic}"
    - Tổng thời lượng: ${durationSec} giây (cần phân bổ chính xác).
    - Bối cảnh: "${background}"
    - Phong cách phân tích: "${styleAnalysis}"

    YÊU CẦU FORMAT OUTPUT (BẮT BUỘC ĐÚNG TỪNG CHỮ):
    1. Tiêu đề: "DÀN Ý CHI TIẾT: ${topic.toUpperCase()} (${durationSec} GIÂY)"

    2. Chia thành 4-8 PHẦN (PHẦN 1, PHẦN 2... PHẦN CUỐI).
    3. Định dạng mỗi phần:
       PHẦN [X]: [Tên phần hấp dẫn] (Phút [M:SS] - Phút [M:SS])
       1) Bối cảnh: [Mô tả chi tiết môi trường, ánh sáng]
       2) Hình ảnh: 
          - Cảnh 1 (0:00 - 0:08): [Mô tả hành động, góc máy]
          - Cảnh 2 ([Time] - [Time]): ...
       3) Âm thanh: [Nhạc nền, hiệu ứng âm thanh SFX]
       4) Nội dung lời dẫn/Text: [Script lời đọc hoặc chữ hiện trên màn hình]

    LƯU Ý QUAN TRỌNG:
    - Tổng thời gian của tất cả các PHẦN phải khớp tuyệt đối từ 0:00 đến ${durationSec}s.
    - Cấu trúc logic: Intro/Hook mạnh mẽ -> Nội dung chính -> Hoàn thiện/Kết nối -> Outro/CTA.
    - Nội dung phải sáng tạo, hấp dẫn và bám sát phong cách "${styleAnalysis}".`;

    const response = await this.ai.models.generateContent({ model: this.modelName, contents: prompt });
    return response.text || '';
  }

  async generatePrompts(timeline: string, background: string, visualStyle: string, aspectRatio: string, N: number, voiceLang: string): Promise<any[]> {
    const prompt = `Dựa trên dàn ý: ${timeline}
    Bối cảnh: ${background}, Style: ${visualStyle}, Ratio: ${aspectRatio}, Voice: ${voiceLang}, Số đoạn: ${N}.
    Tạo bảng 3 cột STT | PROMPT (EN) | VOICE (${voiceLang}). 
    Prompt EN cực kỳ chi tiết về hình ảnh, camera, ánh sáng + "Negative: blurry, low quality, jitter, distorted, text artifacts, watermark".
    Voice dài ~8s (khoảng 18-25 từ cho Tiếng Việt). 
    Trả về JSON array đúng số lượng ${N} phần.`;
    const response = await this.ai.models.generateContent({
      model: this.modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              stt: { type: Type.NUMBER },
              prompt: { type: Type.STRING },
              voice: { type: Type.STRING }
            },
            required: ["stt", "prompt", "voice"]
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GeminiService } from './services/geminiService';
import { VideoConfig, VideoMode, VisualStyle, PromptRow } from './types';

// Helper components
const Button: React.FC<{ 
  onClick?: () => void; 
  disabled?: boolean; 
  className?: string; 
  loading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'success' | 'outline';
  children: React.ReactNode;
}> = ({ onClick, disabled, className = '', loading, variant = 'primary', children }) => {
  const baseStyles = "px-6 py-2.5 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-gray-700 hover:bg-gray-600 text-white border border-gray-600",
    danger: "bg-red-600 hover:bg-red-700 text-white",
    success: "bg-emerald-600 hover:bg-emerald-700 text-white",
    outline: "bg-blue-900/10 hover:bg-blue-900/30 text-blue-400 border border-blue-800/50",
    ghost: "bg-transparent hover:bg-gray-800 text-gray-300"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled || loading} 
      className={`${baseStyles} ${variants[variant]} ${className}`}
    >
      {loading ? <i className="fas fa-spinner fa-spin"></i> : children}
    </button>
  );
};

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
  <div className={`bg-[#111827] border border-gray-800 rounded-xl p-6 shadow-2xl ${className}`}>
    <h3 className="text-lg font-bold mb-6 text-blue-500 flex items-center gap-3">
      <div className="w-1.5 h-7 bg-blue-600 rounded-full shadow-[0_0_10px_rgba(37,99,235,0.5)]"></div>
      {title}
    </h3>
    {children}
  </div>
);

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => {
  const steps = ["Hệ thống", "Nội dung", "Cấu hình", "Dàn ý", "Hoàn tất"];
  return (
    <div className="flex items-center justify-between mb-12 max-w-4xl mx-auto px-4">
      {steps.map((step, idx) => (
        <React.Fragment key={idx}>
          <div className="flex flex-col items-center relative z-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${
              idx <= currentStep ? "bg-blue-600 border-blue-600 text-white scale-110 shadow-lg shadow-blue-900/40" : "border-gray-800 text-gray-600 bg-gray-900"
            }`}>
              {idx < currentStep ? <i className="fas fa-check text-sm"></i> : idx + 1}
            </div>
            <span className={`text-[10px] uppercase tracking-widest mt-3 font-black ${idx <= currentStep ? "text-blue-500" : "text-gray-700"}`}>
              {step}
            </span>
          </div>
          {idx < steps.length - 1 && (
            <div className={`flex-1 h-0.5 mx-2 rounded-full transition-all duration-700 ${idx < currentStep ? "bg-blue-600" : "bg-gray-800"}`}></div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
};

export default function App() {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSystemReady, setIsSystemReady] = useState(false);

  const [config, setConfig] = useState<VideoConfig>({
    summary: '',
    styleAnalysis: '',
    mode: VideoMode.Similar,
    topic: '',
    visualStyle: VisualStyle.Cinematic,
    aspectRatio: '16:9',
    durationMin: 1,
    voiceLang: 'Tiếng Việt',
    channelName: '',
    background: '',
    timeline: '',
    prompts: []
  });

  const gemini = useMemo(() => new GeminiService(), []);

  // Step 0: Verification
  useEffect(() => {
    if (step === 0) {
      const init = async () => {
        setLoading(true);
        try {
          await gemini.verifyKey();
          setIsSystemReady(true);
          setTimeout(() => setStep(1), 500);
        } catch (err: any) {
          setError(err.message === 'QUOTA_EXHAUSTED' ? "Hệ thống quá tải. Thử lại sau." : "Lỗi API.");
        } finally {
          setLoading(false);
        }
      };
      init();
    }
  }, [step, gemini]);

  const handleApiError = useCallback((err: any) => {
    if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
      setError("Cảnh báo: Hết Quota API!");
    } else {
      setError(err.message || "Đã xảy ra lỗi.");
    }
  }, []);

  const handleNextFromStep1 = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await gemini.generateInitialSetup(config.summary, config.styleAnalysis, config.mode, config.visualStyle);
      setConfig(prev => ({ ...prev, topic: result.topic, background: result.background }));
      setStep(2);
    } catch (err) {
      handleApiError(err);
      setStep(2); 
    } finally {
      setLoading(false);
    }
  };

  const regenerateTopic = async () => {
    setLoading(true);
    try {
      const topic = await gemini.generateTopic(config.summary, config.styleAnalysis, config.mode);
      const bg = await gemini.generateBackground(topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, topic, background: bg }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const regenerateBackground = async () => {
    setLoading(true);
    try {
      const bg = await gemini.generateBackground(config.topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, background: bg }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const handleGenerateTimelineFromStep2 = async () => {
    setLoading(true);
    setError(null);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
      setStep(3);
    } catch (err) {
      handleApiError(err);
      setStep(3);
    } finally {
      setLoading(false);
    }
  };

  const generateTimelineAgain = async () => {
    setLoading(true);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const generatePrompts = async () => {
    setLoading(true);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const numSegments = Math.ceil(config.durationMin * 60 / 8);
      const prompts = await gemini.generatePrompts(config.timeline, config.background, config.visualStyle, config.aspectRatio, numSegments, config.voiceLang);
      setConfig(prev => ({ ...prev, prompts }));
      setStep(4);
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const copyPrompts = () => {
    const text = config.prompts.map(p => `STT: ${p.stt}\nPROMPT: ${p.prompt}\nVOICE: ${p.voice}\n---`).join('\n');
    navigator.clipboard.writeText(text);
    alert('Đã copy bảng prompt!');
  };

  const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
  const numSegments = Math.ceil(config.durationMin * 60 / 8);

  return (
    <div className="min-h-screen pb-20 bg-[#070b14] text-gray-100 font-['Inter']">
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 py-4 px-6 sticky top-0 z-50 shadow-xl">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg">
              <i className="fas fa-bolt text-white"></i>
            </div>
            <h1 className="text-xl font-black tracking-tighter">VIDEO WIZARD <span className="text-blue-500">AI</span></h1>
          </div>
          {isSystemReady && (
            <div className="text-[10px] font-bold text-emerald-400 bg-emerald-950/20 px-3 py-1 rounded-full border border-emerald-800/50 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
              SYSTEM ACTIVE
            </div>
          )}
        </div>
      </header>

      <main className="max-w-5xl mx-auto mt-12 px-4">
        {step > 0 && <StepIndicator currentStep={step} />}

        {error && (
          <div className="bg-red-950/40 border border-red-800/50 text-red-200 px-5 py-3 rounded-xl mb-8 flex items-center gap-3 animate-in fade-in zoom-in duration-300">
            <i className="fas fa-exclamation-triangle text-red-500"></i>
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}

        {/* STEP 0: INIT */}
        {step === 0 && (
          <div className="flex flex-col items-center justify-center mt-32 space-y-4">
            <div className="w-12 h-12 border-4 border-blue-900/30 border-t-blue-500 rounded-full animate-spin"></div>
            <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Phân tích hệ thống...</p>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {step === 1 && (
          <div className="space-y-8 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="grid md:grid-cols-2 gap-8">
              <Card title="Tóm tắt nội dung">
                <textarea 
                  className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-4 h-64 outline-none focus:border-blue-500 transition-all font-medium text-gray-300 placeholder:text-gray-700 resize-none custom-scrollbar"
                  placeholder="Nhập nội dung video bạn muốn..."
                  value={config.summary}
                  onChange={(e) => setConfig(prev => ({ ...prev, summary: e.target.value }))}
                />
              </Card>
              <Card title="Phân tích phong cách">
                <textarea 
                  className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-4 h-64 outline-none focus:border-blue-500 transition-all font-medium text-gray-300 placeholder:text-gray-700 resize-none custom-scrollbar"
                  placeholder="Nhịp điệu, âm thanh, màu sắc, ánh sáng..."
                  value={config.styleAnalysis}
                  onChange={(e) => setConfig(prev => ({ ...prev, styleAnalysis: e.target.value }))}
                />
              </Card>
            </div>
            <div className="grid grid-cols-2 gap-6">
               <div 
                onClick={() => setConfig(prev => ({ ...prev, mode: VideoMode.Similar }))}
                className={`cursor-pointer p-6 rounded-2xl border-2 transition-all duration-300 ${config.mode === VideoMode.Similar ? "border-blue-600 bg-blue-900/10 shadow-lg shadow-blue-900/10" : "border-gray-900 bg-gray-950 hover:border-gray-800"}`}
               >
                 <h4 className="font-black text-lg mb-2 flex items-center gap-3">
                   <div className={`w-5 h-5 rounded-full border-4 transition-all ${config.mode === VideoMode.Similar ? "border-blue-500 bg-blue-500/20" : "border-gray-800"}`}></div>
                   Tạo Video Tương Tự
                 </h4>
                 <p className="text-xs text-gray-500 leading-relaxed font-medium">Giữ nguyên trục nội dung gốc, AI sẽ viết lại kịch bản mới hay hơn, tránh trùng lặp.</p>
               </div>
               <div 
                onClick={() => setConfig(prev => ({ ...prev, mode: VideoMode.Different }))}
                className={`cursor-pointer p-6 rounded-2xl border-2 transition-all duration-300 ${config.mode === VideoMode.Different ? "border-blue-600 bg-blue-900/10 shadow-lg shadow-blue-900/10" : "border-gray-900 bg-gray-950 hover:border-gray-800"}`}
               >
                 <h4 className="font-black text-lg mb-2 flex items-center gap-3">
                   <div className={`w-5 h-5 rounded-full border-4 transition-all ${config.mode === VideoMode.Different ? "border-blue-500 bg-blue-500/20" : "border-gray-800"}`}></div>
                   Tạo Chủ Đề Khác Biệt
                 </h4>
                 <p className="text-xs text-gray-500 leading-relaxed font-medium">Chủ đề hoàn toàn mới dựa trên bối cảnh và phong cách của bạn, tránh vi phạm bản quyền.</p>
               </div>
            </div>
            <div className="flex justify-end">
              <Button onClick={handleNextFromStep1} disabled={!config.summary || !config.styleAnalysis || loading} loading={loading} className="w-56 shadow-2xl">
                Phân tích & Tiếp tục <i className="fas fa-arrow-right ml-2 text-xs"></i>
              </Button>
            </div>
          </div>
        )}

        {/* STEP 2: CONFIG */}
        {step === 2 && (
          <div className="space-y-8 animate-in slide-in-from-right-10 duration-500">
            <Card title="Chủ đề & Bối cảnh (AI Tự động)">
              <div className="space-y-8">
                <div>
                  <div className="flex justify-between items-center mb-3 px-1">
                    <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest">Chủ đề mới muốn làm</label>
                    <Button variant="outline" onClick={regenerateTopic} loading={loading} className="py-1 px-4 text-[10px] rounded-lg h-8">
                      <i className="fas fa-wand-sparkles mr-1"></i> AI Tự tạo
                    </Button>
                  </div>
                  <textarea 
                    className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-5 h-24 outline-none focus:border-blue-500 transition-all text-gray-300 font-bold resize-none custom-scrollbar"
                    value={config.topic}
                    onChange={(e) => setConfig(prev => ({ ...prev, topic: e.target.value }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-3 px-1">
                    <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest">Bối cảnh / Nền tảng (Auto-fill)</label>
                    <Button variant="outline" onClick={regenerateBackground} loading={loading} className="py-1 px-4 text-[10px] rounded-lg h-8">
                      <i className="fas fa-sync mr-1"></i> Tạo lại bối cảnh
                    </Button>
                  </div>
                  <textarea 
                    className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-5 h-28 outline-none focus:border-blue-500 transition-all text-gray-400 font-medium resize-none custom-scrollbar"
                    value={config.background}
                    onChange={(e) => setConfig(prev => ({ ...prev, background: e.target.value }))}
                  />
                </div>
              </div>
            </Card>

            <div className="grid md:grid-cols-2 gap-8">
              <Card title="Phong cách thị giác">
                <div className="grid grid-cols-2 gap-3">
                  {Object.values(VisualStyle).map(v => (
                    <button key={v} onClick={() => setConfig(prev => ({ ...prev, visualStyle: v }))} className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border-2 ${config.visualStyle === v ? "bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-900/20 scale-[1.02]" : "bg-gray-900 border-gray-800 text-gray-600 hover:border-gray-700"}`}>{v}</button>
                  ))}
                </div>
              </Card>
              <Card title="Kỹ thuật video">
                 <div className="space-y-6">
                   <div className="flex gap-4">
                     <button onClick={() => setConfig(prev => ({ ...prev, aspectRatio: '16:9' }))} className={`flex-1 py-3 rounded-xl border-2 font-black transition-all ${config.aspectRatio === '16:9' ? "bg-blue-600 border-blue-600 text-white" : "bg-gray-900 border-gray-800 text-gray-600"}`}>16:9</button>
                     <button onClick={() => setConfig(prev => ({ ...prev, aspectRatio: '9:16' }))} className={`flex-1 py-3 rounded-xl border-2 font-black transition-all ${config.aspectRatio === '9:16' ? "bg-blue-600 border-blue-600 text-white" : "bg-gray-900 border-gray-800 text-gray-600"}`}>9:16</button>
                   </div>
                   <div className="flex items-end gap-6">
                     <div className="flex-1">
                       <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2 block">Thời lượng (Phút)</label>
                       <input type="number" step="0.5" className="w-full bg-gray-900 border border-gray-800 rounded-xl px-4 py-3 font-bold text-center outline-none focus:border-blue-500" value={config.durationMin} onChange={(e) => setConfig(prev => ({ ...prev, durationMin: parseFloat(e.target.value) }))} />
                     </div>
                     <div className="bg-blue-900/10 p-3 rounded-xl border border-blue-800/30 flex-1 text-center">
                        <p className="text-[9px] font-black text-blue-500 uppercase">Segments x 8s</p>
                        <p className="text-xl font-black text-blue-400">{numSegments}</p>
                        <p className="text-[10px] text-gray-600 font-bold">{durationSecActual}s (~{(durationSecActual/60).toFixed(1)}p)</p>
                     </div>
                   </div>
                 </div>
              </Card>
            </div>

            <div className="flex justify-between pt-8 border-t border-gray-900">
              <Button variant="ghost" onClick={() => setStep(1)}>Quay lại</Button>
              <Button onClick={handleGenerateTimelineFromStep2} disabled={!config.topic || loading} loading={loading} className="w-64 shadow-2xl shadow-blue-900/30">Tạo dàn ý Timeline <i className="fas fa-list-check ml-2"></i></Button>
            </div>
          </div>
        )}

        {/* STEP 3: TIMELINE */}
        {step === 3 && (
          <div className="space-y-8 animate-in slide-in-from-bottom-10 duration-500">
            <div className="flex justify-between items-end">
               <div>
                 <h2 className="text-2xl font-black text-white">{config.topic.toUpperCase()}</h2>
                 <p className="text-blue-500 font-black text-sm uppercase tracking-widest mt-1">Timeline Detail Board • {durationSecActual}s</p>
               </div>
               <Button onClick={generateTimelineAgain} loading={loading} variant={config.timeline ? "outline" : "primary"}>
                 <i className="fas fa-wand-magic-sparkles mr-2"></i> {config.timeline ? "Làm mới Timeline" : "AI Tạo Timeline"}
               </Button>
            </div>
            <Card title="Trình soạn thảo chi tiết">
              <div className="mb-6 bg-blue-950/20 border border-blue-900/30 p-5 rounded-xl text-xs text-blue-300 font-bold flex gap-4 items-center shadow-lg">
                <i className="fas fa-info-circle text-xl text-blue-600"></i>
                <p>Kiểm tra và chỉnh sửa dàn ý chi tiết bên dưới… đảm bảo logic từng phút trước khi tiếp tục.</p>
              </div>
              <textarea 
                className="w-full bg-[#050810] border border-gray-900 rounded-2xl p-8 h-[550px] outline-none font-mono text-sm leading-8 text-gray-400 custom-scrollbar shadow-inner focus:border-blue-600 transition-all"
                value={config.timeline}
                onChange={(e) => setConfig(prev => ({ ...prev, timeline: e.target.value }))}
                placeholder="AI đang chuẩn bị dàn ý..."
              />
            </Card>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(2)}>Quay lại cấu hình</Button>
              <Button onClick={generatePrompts} disabled={!config.timeline || loading} loading={loading} variant="success" className="w-64 shadow-2xl">
                TIẾP TỤC TẠO PROMPT <i className="fas fa-rocket ml-2"></i>
              </Button>
            </div>
          </div>
        )}

        {/* STEP 4: PROMPTS */}
        {step === 4 && (
          <div className="space-y-10 animate-in zoom-in duration-500">
            <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-10 rounded-3xl border border-gray-800 shadow-3xl gap-8">
               <div className="text-center md:text-left">
                 <h2 className="text-3xl font-black text-white">HOÀN TẤT CẤU TRÚC</h2>
                 <p className="text-gray-500 mt-2 font-bold uppercase tracking-widest text-[10px]">Bảng Prompt & Voice-over đã sẵn sàng</p>
