              <Button onClick={generatePrompts} disabled={!config.timeline || loading} loading={loading} variant="success" className="w-64 shadow-2xl">
                TIẾP TỤC TẠO PROMPT <i className="fas fa-rocket ml-2"></i>
              </Button>
            </div>
          </div>
        )}

        {/* STEP 4: FINAL */}
        {step === 4 && (
          <div className="space-y-10 animate-in zoom-in duration-500">
            <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-8 rounded-3xl border border-gray-800 shadow-3xl gap-6">
               <div className="text-center md:text-left">
                 <h2 className="text-2xl font-black text-white">HOÀN TẤT CẤU TRÚC</h2>
                 <p className="text-gray-500 mt-1 font-bold uppercase tracking-widest text-[9px]">Tải xuống nội dung cho video của bạn</p>
               </div>
               <div className="grid grid-cols-2 md:flex gap-3 w-full md:w-auto">
                 <Button onClick={downloadPrompts} variant="info" className="text-xs">
                   <i className="fas fa-file-export mr-2"></i> Tải Prompt
                 </Button>
                 <Button onClick={downloadVoices} variant="success" className="text-xs">
                   <i className="fas fa-microphone mr-2"></i> Tải Voice
                 </Button>
                 <Button onClick={() => setStep(3)} variant="neon-yellow" className="text-xs">
                   <i className="fas fa-chevron-left mr-2"></i> Quay lại
                 </Button>
                 <Button onClick={startNew} variant="danger" className="text-xs">
                   <i className="fas fa-plus mr-2"></i> Tạo mới
                 </Button>
               </div>
            </div>

            <div className="bg-[#0b1121] border border-gray-900 rounded-3xl overflow-hidden shadow-inner">
               <div className="bg-gray-900/50 px-8 py-5 border-b border-gray-800 flex justify-between items-center">
                  <span className="text-[10px] font-black uppercase tracking-widest text-gray-600">Video Board</span>
                  <span className="text-[10px] font-black uppercase text-blue-500 bg-blue-900/20 px-3 py-1 rounded-full">{numSegments} Segments x 8s</span>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead>
                      <tr className="bg-black/20 text-[10px] font-black uppercase tracking-widest text-gray-700">
                        <th className="px-8 py-6 w-20">STT</th>
                        <th className="px-8 py-6">Prompt Hình Ảnh (EN)</th>
                        <th className="px-8 py-6 w-1/3 border-l border-gray-800">Lời dẫn Voice</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-900">
                      {config.prompts.map((p, i) => (
                        <tr key={i} className="group hover:bg-blue-600/[0.03] transition-all">
                          <td className="px-8 py-8 font-black text-blue-500 text-xl align-top">{p.stt}</td>
                          <td className="px-8 py-8 align-top">
                            <div className="bg-black/30 p-5 rounded-2xl border border-gray-800 text-gray-400 text-xs leading-relaxed font-medium group-hover:border-gray-600 transition-all">{p.prompt}</div>
                          </td>
                          <td className="px-8 py-8 align-top border-l border-gray-800">
                             <div className="text-blue-100 font-bold leading-relaxed text-sm italic">
                                "{p.voice}"
                             </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                 </table>
               </div>
            </div>
          </div>
        )}
      </main>

      {/* GLOBAL LOADING */}
      {loading && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center animate-in fade-in">
          <div className="bg-[#111827] border border-gray-800 p-12 rounded-[2.5rem] shadow-3xl flex flex-col items-center max-w-sm w-full mx-4 border-t-blue-600 border-t-4">
             <div className="relative mb-8">
               <div className="w-20 h-20 border-4 border-blue-900/30 border-t-blue-500 rounded-full animate-spin"></div>
               <div className="absolute inset-0 flex items-center justify-center">
                 <i className="fas fa-brain text-blue-500 animate-pulse text-2xl"></i>
               </div>
             </div>
             <h3 className="text-white font-black uppercase tracking-widest text-sm mb-3">Đang xử lý dữ liệu...</h3>
             <p className="text-gray-500 text-[10px] font-bold text-center leading-relaxed">Gemini AI đang tối ưu hóa kịch bản của bạn. Vui lòng không đóng cửa sổ này.</p>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GeminiService } from './services/geminiService';
import { VideoConfig, VideoMode, VisualStyle, PromptRow } from './types';

// Helper components
const Button: React.FC<{ 
  onClick?: () => void; 
  disabled?: boolean; 
  className?: string; 
  loading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger' | 'success' | 'outline' | 'ghost' | 'info' | 'gemini' | 'neon-yellow';
  children: React.ReactNode;
}> = ({ onClick, disabled, className = '', loading, variant = 'primary', children }) => {
  const baseStyles = "px-6 py-2.5 rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-gray-700 hover:bg-gray-600 text-white border border-gray-600",
    danger: "bg-red-600 hover:bg-red-700 text-white",
    success: "bg-emerald-600 hover:bg-emerald-700 text-white",
    outline: "bg-blue-900/10 hover:bg-blue-900/30 text-blue-400 border border-blue-800/50",
    info: "bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg",
    gemini: "bg-[#d32f6f] hover:bg-[#e91e63] text-white shadow-[0_0_20px_rgba(211,47,111,0.4)] font-bold px-10 py-3 rounded-full transition-transform active:scale-95",
    'neon-yellow': "bg-[#ccff00] hover:bg-[#b3e600] text-black font-bold shadow-[0_0_20px_rgba(204,255,0,0.6)] border-none hover:scale-105 active:scale-95",
    ghost: "bg-transparent hover:bg-gray-800 text-gray-300"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled || loading} 
      className={`${baseStyles} ${variants[variant]} ${className}`}
    >
      {loading ? <i className="fas fa-spinner fa-spin"></i> : children}
    </button>
  );
};

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className = '' }) => (
  <div className={`bg-[#111827] border border-gray-800 rounded-xl p-6 shadow-2xl ${className}`}>
    <h3 className="text-lg font-bold mb-6 text-blue-500 flex items-center gap-3">
      <div className="w-1.5 h-7 bg-blue-600 rounded-full shadow-[0_0_10px_rgba(37,99,235,0.5)]"></div>
      {title}
    </h3>
    {children}
  </div>
);

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => {
  const steps = ["Hệ thống", "Nội dung", "Cấu hình", "Dàn ý", "Hoàn tất"];
  return (
    <div className="flex items-center justify-between mb-12 max-w-4xl mx-auto px-4">
      {steps.map((step, idx) => (
        <React.Fragment key={idx}>
          <div className="flex flex-col items-center relative z-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${
              idx <= currentStep ? "bg-blue-600 border-blue-600 text-white scale-110 shadow-lg shadow-blue-900/40" : "border-gray-800 text-gray-600 bg-gray-900"
            }`}>
              {idx < currentStep ? <i className="fas fa-check text-sm"></i> : idx + 1}
            </div>
            <span className={`text-[10px] uppercase tracking-widest mt-3 font-black ${idx <= currentStep ? "text-blue-500" : "text-gray-700"}`}>
              {step}
            </span>
          </div>
          {idx < steps.length - 1 && (
            <div className={`flex-1 h-0.5 mx-2 rounded-full transition-all duration-700 ${idx < currentStep ? "bg-blue-600" : "bg-gray-800"}`}></div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
};

export default function App() {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSystemReady, setIsSystemReady] = useState(false);

  const [config, setConfig] = useState<VideoConfig>({
    summary: '',
    styleAnalysis: '',
    mode: VideoMode.Different,
    topic: '',
    visualStyle: VisualStyle.Cinematic,
    aspectRatio: '16:9',
    durationMin: 1,
    voiceLang: 'Tiếng Việt',
    channelName: '',
    background: '',
    timeline: '',
    prompts: []
  });

  const gemini = useMemo(() => new GeminiService(), []);

  useEffect(() => {
    if (step === 0) {
      const init = async () => {
        setLoading(true);
        try {
          await gemini.verifyKey();
          setIsSystemReady(true);
          setTimeout(() => setStep(1), 500);
        } catch (err: any) {
          setError(err.message === 'QUOTA_EXHAUSTED' ? "Hệ thống quá tải. Thử lại sau." : "Lỗi API.");
        } finally {
          setLoading(false);
        }
      };
      init();
    }
  }, [step, gemini]);

  const handleApiError = useCallback((err: any) => {
    if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
      setError("Cảnh báo: Hết Quota API!");
    } else {
      setError(err.message || "Đã xảy ra lỗi.");
    }
  }, []);

  const handleNextFromStep1 = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await gemini.generateInitialSetup(config.summary, config.styleAnalysis, config.mode, config.visualStyle);
      setConfig(prev => ({ ...prev, topic: result.topic, background: result.background }));
      setStep(2);
    } catch (err) {
      handleApiError(err);
      setStep(2); 
    } finally {
      setLoading(false);
    }
  };

  const regenerateTopic = async () => {
    setLoading(true);
    try {
      const topic = await gemini.generateTopic(config.summary, config.styleAnalysis, config.mode);
      const bg = await gemini.generateBackground(topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, topic, background: bg }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const regenerateBackground = async () => {
    setLoading(true);
    try {
      const bg = await gemini.generateBackground(config.topic, config.visualStyle, config.styleAnalysis);
      setConfig(prev => ({ ...prev, background: bg }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const handleGenerateTimelineFromStep2 = async () => {
    setLoading(true);
    setError(null);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
      setStep(3);
    } catch (err) {
      handleApiError(err);
      setStep(3);
    } finally {
      setLoading(false);
    }
  };

  const generateTimelineAgain = async () => {
    setLoading(true);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const tl = await gemini.generateTimeline(config.topic, config.background, durationSecActual, config.styleAnalysis);
      setConfig(prev => ({ ...prev, timeline: tl }));
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const generatePrompts = async () => {
    setLoading(true);
    try {
      const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
      const numSegments = Math.ceil(config.durationMin * 60 / 8);
      const prompts = await gemini.generatePrompts(config.timeline, config.background, config.visualStyle, config.aspectRatio, numSegments, config.voiceLang);
      setConfig(prev => ({ ...prev, prompts }));
      setStep(4);
    } catch (err) { handleApiError(err); }
    finally { setLoading(false); }
  };

  const downloadPrompts = () => {
    const text = config.prompts.map(p => p.prompt).join('\n\n');
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Prompts_${config.topic.replace(/\s+/g, '_')}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const downloadVoices = () => {
    const text = config.prompts.map(p => p.voice).join('\n');
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Voices_${config.topic.replace(/\s+/g, '_')}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const startNew = () => {
    if (confirm("Xác nhận tạo mới từ đầu? Hệ thống sẽ quay trở lại Bước 1.")) {
      setConfig({
        summary: '',
        styleAnalysis: '',
        mode: VideoMode.Different,
        topic: '',
        visualStyle: VisualStyle.Cinematic,
        aspectRatio: '16:9',
        durationMin: 1,
        voiceLang: 'Tiếng Việt',
        channelName: '',
        background: '',
        timeline: '',
        prompts: []
      });
      setStep(1);
    }
  };

  const durationSecActual = Math.ceil(config.durationMin * 60 / 8) * 8;
  const numSegments = Math.ceil(config.durationMin * 60 / 8);

  return (
    <div className="min-h-screen pb-20 bg-[#070b14] text-gray-100 font-['Inter']">
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 py-4 px-6 sticky top-0 z-50 shadow-xl">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-full overflow-hidden shadow-lg border-2 border-white bg-gray-900">
              <img 
                src="https://yt3.googleusercontent.com/Gug5UDLjPMRBto68HqZvJCSryebEkqiI2_9qV_8y16ZKIVLgxYBFx_PyUYZStcTzSc3v7TLq=s900-c-k-c0x00ffffff-no-rj" 
                alt="Văn Thế Web Logo"
                className="w-full h-full object-cover"
              />
            </div>
            <h1 className="text-xl font-black tracking-tighter">Công Nghệ Video Ai Bán Content Văn Thế Web V1.0</h1>
          </div>
          {isSystemReady && (
            <div className="text-[10px] font-bold text-emerald-400 bg-emerald-950/20 px-3 py-1 rounded-full border border-emerald-800/50 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
              SYSTEM ACTIVE
            </div>
          )}
        </div>
      </header>

      <main className="max-w-5xl mx-auto mt-12 px-4">
        {step > 0 && <StepIndicator currentStep={step} />}

        {error && (
          <div className="bg-red-950/40 border border-red-800/50 text-red-200 px-5 py-3 rounded-xl mb-8 flex items-center gap-3">
            <i className="fas fa-exclamation-triangle text-red-500"></i>
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {step === 1 && (
          <div className="space-y-8 animate-in fade-in slide-in-from-top-4 duration-500">
            {/* Guide Section */}
            <div className="bg-[#0b172a] border border-cyan-900/40 rounded-xl p-6 shadow-xl space-y-4">
              <div className="flex gap-4 items-start">
                <div className="mt-1 flex-shrink-0">
                   <div className="w-6 h-6 rounded-full border border-cyan-400/50 flex items-center justify-center text-cyan-400 text-xs font-bold">i</div>
                </div>
                <div className="space-y-2 text-sm leading-relaxed">
                  <p className="text-cyan-50/90 font-medium">
                    Cách lấy thông tin video: copy đường link video rồi đưa vào Gemini kết hợp với câu lệnh <span className="italic font-bold">"Phân tích cho tôi Nội dung và phong cách video trên"</span>.
                  </p>
                  <p className="text-[#f5a623] font-bold">
                    Ví dụ: https://www.youtube.com/watch?v=... Phân tích cho tôi Nội dung và phong cách video trên
                  </p>
                </div>
              </div>
              <div className="flex justify-center pt-2">
                <a href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">
                  <Button variant="gemini">
                    Gemini AI <i className="fas fa-external-link-alt ml-2 text-xs"></i>
                  </Button>
                </a>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
              <Card title="Tóm tắt nội dung">
                <textarea 
                  className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-4 h-64 outline-none focus:border-blue-500 transition-all font-medium text-gray-300 placeholder:text-gray-700 resize-none custom-scrollbar"
                  placeholder="Nhập nội dung video bạn muốn..."
                  value={config.summary}
                  onChange={(e) => setConfig(prev => ({ ...prev, summary: e.target.value }))}
                />
              </Card>
              <Card title="Phân tích phong cách">
                <textarea 
                  className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-4 h-64 outline-none focus:border-blue-500 transition-all font-medium text-gray-300 placeholder:text-gray-700 resize-none custom-scrollbar"
                  placeholder="Nhịp điệu, âm thanh, màu sắc, ánh sáng..."
                  value={config.styleAnalysis}
                  onChange={(e) => setConfig(prev => ({ ...prev, styleAnalysis: e.target.value }))}
                />
              </Card>
            </div>

            {/* Mode status indicator (Static, since choice is removed) */}
            <div className="flex justify-center">
              <div className="bg-blue-900/10 border border-blue-800/30 px-6 py-4 rounded-2xl flex items-center gap-4 max-w-md w-full shadow-lg">
                <div className="w-4 h-4 rounded-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]"></div>
                <div>
                   <h4 className="font-black text-blue-400 text-sm uppercase">Chế độ: Tạo Chủ Đề Khác Biệt</h4>
                   <p className="text-[10px] text-gray-500 font-medium">AI sẽ đề xuất chủ đề mới hoàn toàn dựa trên bối cảnh bạn cung cấp.</p>
                </div>
              </div>
            </div>

            <div className="flex justify-end">
              <Button onClick={handleNextFromStep1} disabled={!config.summary || !config.styleAnalysis || loading} loading={loading} className="w-56 shadow-2xl">
                Phân tích & Tiếp tục <i className="fas fa-arrow-right ml-2 text-xs"></i>
              </Button>
            </div>
          </div>
        )}

        {/* STEP 2: CONFIG */}
        {step === 2 && (
          <div className="space-y-8 animate-in slide-in-from-right-10 duration-500">
            <Card title="Chủ đề & Bối cảnh (AI Tự động)">
              <div className="space-y-8">
                <div>
                  <div className="flex justify-between items-center mb-3 px-1">
                    <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest">Chủ đề mới muốn làm</label>
                    <Button variant="outline" onClick={regenerateTopic} loading={loading} className="py-1 px-4 text-[10px] rounded-lg h-8">
                      <i className="fas fa-wand-sparkles mr-1"></i> AI Tự tạo
                    </Button>
                  </div>
                  <textarea 
                    className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-5 h-24 outline-none focus:border-blue-500 transition-all text-gray-300 font-bold resize-none custom-scrollbar"
                    value={config.topic}
                    onChange={(e) => setConfig(prev => ({ ...prev, topic: e.target.value }))}
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-3 px-1">
                    <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest">Bối cảnh / Nền tảng (Auto-fill)</label>
                    <Button variant="outline" onClick={regenerateBackground} loading={loading} className="py-1 px-4 text-[10px] rounded-lg h-8">
                      <i className="fas fa-sync mr-1"></i> Tạo lại bối cảnh
                    </Button>
                  </div>
                  <textarea 
                    className="w-full bg-[#0a0f1d] border border-gray-800 rounded-xl p-5 h-28 outline-none focus:border-blue-500 transition-all text-gray-400 font-medium resize-none custom-scrollbar"
                    value={config.background}
                    onChange={(e) => setConfig(prev => ({ ...prev, background: e.target.value }))}
                  />
                </div>
              </div>
            </Card>

            <div className="grid md:grid-cols-2 gap-8">
              <Card title="Phong cách thị giác">
                <div className="grid grid-cols-2 gap-3">
                  {Object.values(VisualStyle).map(v => (
                    <button key={v} onClick={() => setConfig(prev => ({ ...prev, visualStyle: v }))} className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border-2 ${config.visualStyle === v ? "bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-900/20" : "bg-gray-900 border-gray-800 text-gray-600 hover:border-gray-700"}`}>{v}</button>
                  ))}
                </div>
