        styleAnalysis: '',
        mode: VideoMode.Different,
        topic: '',
        visualStyle: VisualStyle.Cinematic,
        aspectRatio: '16:9',
        durationMin: 1,
        voiceLang: 'Tiếng Việt',
        channelName: '',
        background: '',
        timeline: '',
        prompts: []
      });
      setStep(0); // Quay lại bước 0 để kiểm tra lại hệ thống và reset wizard
    }
