                  <div className="grid grid-cols-3 gap-2">
                    {languages.map(lang => (
                      <button 
                        key={lang} 
                        onClick={() => setConfig(prev => ({ ...prev, voiceLang: lang }))} 
                        className={`py-2 px-1 rounded-lg text-[10px] font-bold transition-all border-2 ${config.voiceLang === lang ? "bg-indigo-600 border-indigo-600 text-white" : "bg-gray-950 border-gray-900 text-gray-500 hover:border-gray-800"}`}
                      >
                        {lang}
