                       <button onClick={() => setConfig(prev => ({ ...prev, aspectRatio: '9:16' }))} className={`flex-1 py-4 rounded-xl border-2 font-black transition-all flex flex-col items-center gap-1 ${config.aspectRatio === '9:16' ? "bg-blue-600 border-blue-600 text-white" : "bg-gray-950 border-gray-900 text-gray-600"}`}>
                         <i className="fas fa-mobile-alt text-lg"></i>
                         <span>9:16 (Dọc)</span>
                       </button>
