                   <div className="flex items-end gap-6 bg-gray-950/50 p-6 rounded-2xl border border-gray-900">
                     <div className="flex-1">
                       <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-3 block">Thời lượng mong muốn (Phút)</label>
                       <input 
                         type="number" 
