                         value={config.durationMin} 
                         onChange={(e) => setConfig(prev => ({ ...prev, durationMin: parseFloat(e.target.value) || 0 }))} 
                       />
                     </div>
                     <div className="bg-blue-900/10 p-4 rounded-xl border border-blue-800/30 flex-1 text-center shadow-lg">
                        <p className="text-[9px] font-black text-blue-500 uppercase tracking-tighter mb-1">Cấu trúc đề xuất</p>
